-- Native calendar foundation only: no business rows, providers, grants or source reads.
CREATE TABLE IF NOT EXISTS conf_calendar_event_type (
  id_calendar_event_type BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna del tipo de evento; nunca un ID ERP',
  public_id_calendar_event_type CHAR(26) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ULID publico del tipo para contratos API',
  module_id_calendar_event_type BIGINT UNSIGNED NOT NULL COMMENT 'Modulo operativo propietario del tipo',
  code_calendar_event_type VARCHAR(80) NOT NULL COMMENT 'Codigo estable del tipo dentro de su modulo',
  name_calendar_event_type VARCHAR(180) NOT NULL COMMENT 'Nombre visible del tipo de evento',
  color_calendar_event_type CHAR(7) NOT NULL COMMENT 'Color hexadecimal RGB del tipo; no expresa permisos ni estados',
  status_calendar_event_type VARCHAR(16) NOT NULL DEFAULT 'active' COMMENT 'Disponibilidad active o inactive para nuevas selecciones',
  created_at_calendar_event_type DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Creacion del tipo en UTC',
  updated_at_calendar_event_type DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima modificacion del tipo en UTC mantenida por trigger',
  PRIMARY KEY (id_calendar_event_type),
  UNIQUE KEY uq_calendar_type_public (public_id_calendar_event_type),
  UNIQUE KEY uq_calendar_type_module_code (module_id_calendar_event_type,code_calendar_event_type),
  UNIQUE KEY uq_calendar_type_module_id (id_calendar_event_type,module_id_calendar_event_type),
  FOREIGN KEY (module_id_calendar_event_type) REFERENCES sec_org_unit(id_org_unit),
  CONSTRAINT ck_calendar_type_color CHECK (color_calendar_event_type REGEXP '^#[0-9A-Fa-f]{6}$'),
  CONSTRAINT ck_calendar_type_status CHECK (status_calendar_event_type IN ('active','inactive')),
  CONSTRAINT ck_calendar_type_name CHECK (CHAR_LENGTH(TRIM(name_calendar_event_type))>0 AND CHAR_LENGTH(TRIM(code_calendar_event_type))>0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tipos y colores por modulo; vacio hasta configurar el calendario';

CREATE TABLE IF NOT EXISTS crm_calendar_event (
  id_calendar_event BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna del evento unico compartido; no se duplica por participante',
  public_id_calendar_event CHAR(26) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ULID publico estable del evento para API y enlaces',
  origin_module_id_calendar_event BIGINT UNSIGNED NOT NULL COMMENT 'Modulo de origen inmutable; editar exige este contexto y permiso efectivo',
  type_id_calendar_event BIGINT UNSIGNED NOT NULL COMMENT 'Tipo definido para el mismo modulo de origen',
  organizer_user_id_calendar_event BIGINT UNSIGNED NOT NULL COMMENT 'Organizador o responsable interno de sec_user; no es un ID externo',
  title_calendar_event VARCHAR(250) NOT NULL COMMENT 'Titulo visible del evento',
  description_calendar_event TEXT NULL COMMENT 'Descripcion del evento; el API futuro valida y escapa su presentacion',
  location_calendar_event VARCHAR(500) NULL COMMENT 'Lugar o descripcion de ubicacion de la cita',
  color_override_calendar_event CHAR(7) NULL COMMENT 'Color RGB opcional del evento; null usa el color del tipo',
  status_calendar_event VARCHAR(24) NOT NULL DEFAULT 'scheduled' COMMENT 'Estado scheduled, completed o cancelled; independiente de respuestas y lectura',
  starts_at_calendar_event DATETIME(3) NOT NULL COMMENT 'Instante inicial UTC; sustituye fechas y horas guardadas como texto',
  ends_at_calendar_event DATETIME(3) NOT NULL COMMENT 'Limite final UTC exclusivo y posterior al inicio',
  timezone_calendar_event VARCHAR(100) NOT NULL COMMENT 'Zona IANA para presentar el horario y calcular el dia local; validacion futura en API',
  all_day_calendar_event TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Uno para todo el dia; limites deben ser medianoches locales verificadas por API',
  cancellation_reason_calendar_event VARCHAR(1000) NULL COMMENT 'Motivo del estado cancelado; no reutiliza banderas ni numeros ambiguos',
  version_calendar_event INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Version optimista que el futuro escritor incrementa al modificar el agregado',
  invitation_version_calendar_event INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Version de invitacion; cambia cuando una reprogramacion exige nueva respuesta',
  created_by_user_id_calendar_event BIGINT UNSIGNED NOT NULL COMMENT 'Usuario interno que creo el evento o registro su importacion autorizada',
  updated_by_user_id_calendar_event BIGINT UNSIGNED NOT NULL COMMENT 'Usuario interno responsable de la ultima modificacion',
  created_at_calendar_event DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Creacion nativa del evento en UTC',
  updated_at_calendar_event DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima modificacion UTC mantenida por trigger',
  deleted_at_calendar_event DATETIME(3) NULL COMMENT 'Borrado logico UTC; no elimina participantes ni auditoria',
  PRIMARY KEY (id_calendar_event),
  UNIQUE KEY uq_calendar_event_public (public_id_calendar_event),
  KEY ix_calendar_event_module_time (origin_module_id_calendar_event,deleted_at_calendar_event,starts_at_calendar_event,id_calendar_event),
  KEY ix_calendar_event_organizer_time (organizer_user_id_calendar_event,deleted_at_calendar_event,starts_at_calendar_event,id_calendar_event),
  KEY ix_calendar_event_end (ends_at_calendar_event,id_calendar_event),
  FOREIGN KEY (origin_module_id_calendar_event) REFERENCES sec_org_unit(id_org_unit),
  FOREIGN KEY (type_id_calendar_event,origin_module_id_calendar_event) REFERENCES conf_calendar_event_type(id_calendar_event_type,module_id_calendar_event_type),
  FOREIGN KEY (organizer_user_id_calendar_event) REFERENCES sec_user(id_user),
  FOREIGN KEY (created_by_user_id_calendar_event) REFERENCES sec_user(id_user),
  FOREIGN KEY (updated_by_user_id_calendar_event) REFERENCES sec_user(id_user),
  CONSTRAINT ck_calendar_event_interval CHECK (ends_at_calendar_event > starts_at_calendar_event),
  CONSTRAINT ck_calendar_event_flags CHECK (all_day_calendar_event IN (0,1) AND version_calendar_event>0 AND invitation_version_calendar_event>0),
  CONSTRAINT ck_calendar_event_status CHECK (status_calendar_event IN ('scheduled','completed','cancelled')),
  CONSTRAINT ck_calendar_event_cancel CHECK (status_calendar_event<>'cancelled' OR (cancellation_reason_calendar_event IS NOT NULL AND CHAR_LENGTH(TRIM(cancellation_reason_calendar_event))>0)),
  CONSTRAINT ck_calendar_event_color CHECK (color_override_calendar_event IS NULL OR color_override_calendar_event REGEXP '^#[0-9A-Fa-f]{6}$'),
  CONSTRAINT ck_calendar_event_text CHECK (CHAR_LENGTH(TRIM(title_calendar_event))>0 AND CHAR_LENGTH(TRIM(timezone_calendar_event))>0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Evento CRM con modulo de origen; lectura compartida no concede edicion';

CREATE TABLE IF NOT EXISTS crm_calendar_participant (
  id_calendar_participant BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna del participante o persona copiada',
  public_id_calendar_participant CHAR(26) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ULID publico de la participacion para responder sin exponer claves internas',
  event_id_calendar_participant BIGINT UNSIGNED NOT NULL COMMENT 'Evento unico al que pertenece esta participacion',
  user_id_calendar_participant BIGINT UNSIGNED NULL COMMENT 'Usuario interno invitado; null solo para un invitado externo por correo',
  external_email_calendar_participant VARCHAR(254) NULL COMMENT 'Correo normalizado del invitado externo; null para usuarios internos',
  display_name_calendar_participant VARCHAR(250) NULL COMMENT 'Nombre visible opcional del invitado externo',
  role_calendar_participant VARCHAR(24) NOT NULL DEFAULT 'required' COMMENT 'Participacion required, optional, copied o coorganizer; no evita controles de modulo',
  status_calendar_participant VARCHAR(16) NOT NULL DEFAULT 'active' COMMENT 'Participacion active o revoked; no se elimina su historia al retirar una invitacion',
  response_calendar_participant VARCHAR(24) NOT NULL DEFAULT 'pending' COMMENT 'Respuesta pending, accepted, tentative, declined o not_required; no es lectura de campana',
  responded_at_calendar_participant DATETIME(3) NULL COMMENT 'Fecha efectiva UTC de la respuesta; null mientras no exista respuesta',
  response_version_calendar_participant INT UNSIGNED NULL COMMENT 'Version de invitacion a la que responde; comparar con la version actual del evento',
  invited_by_user_id_calendar_participant BIGINT UNSIGNED NOT NULL COMMENT 'Usuario interno que agrego a esta persona',
  invitation_sent_at_calendar_participant DATETIME(3) NULL COMMENT 'Envio externo confirmado; no se llena por crear el evento ni por sincronizarlo',
  revoked_at_calendar_participant DATETIME(3) NULL COMMENT 'Fecha UTC de retiro de esta participacion',
  created_at_calendar_participant DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Registro de la participacion en UTC',
  updated_at_calendar_participant DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima modificacion de esta participacion en UTC',
  PRIMARY KEY (id_calendar_participant),
  UNIQUE KEY uq_calendar_participant_public (public_id_calendar_participant),
  UNIQUE KEY uq_calendar_participant_user (event_id_calendar_participant,user_id_calendar_participant),
  UNIQUE KEY uq_calendar_participant_email (event_id_calendar_participant,external_email_calendar_participant),
  KEY ix_calendar_participant_inbox (user_id_calendar_participant,status_calendar_participant,event_id_calendar_participant),
  FOREIGN KEY (event_id_calendar_participant) REFERENCES crm_calendar_event(id_calendar_event),
  FOREIGN KEY (user_id_calendar_participant) REFERENCES sec_user(id_user),
  FOREIGN KEY (invited_by_user_id_calendar_participant) REFERENCES sec_user(id_user),
  CONSTRAINT ck_calendar_participant_identity CHECK ((user_id_calendar_participant IS NOT NULL AND external_email_calendar_participant IS NULL) OR (user_id_calendar_participant IS NULL AND external_email_calendar_participant IS NOT NULL AND CHAR_LENGTH(TRIM(external_email_calendar_participant))>0)),
  CONSTRAINT ck_calendar_participant_role CHECK (role_calendar_participant IN ('required','optional','copied','coorganizer')),
  CONSTRAINT ck_calendar_participant_status CHECK ((status_calendar_participant='active' AND revoked_at_calendar_participant IS NULL) OR (status_calendar_participant='revoked' AND revoked_at_calendar_participant IS NOT NULL)),
  CONSTRAINT ck_calendar_participant_response CHECK ((response_calendar_participant IN ('pending','not_required') AND responded_at_calendar_participant IS NULL AND response_version_calendar_participant IS NULL) OR (response_calendar_participant IN ('accepted','tentative','declined') AND responded_at_calendar_participant IS NOT NULL AND response_version_calendar_participant IS NOT NULL AND response_version_calendar_participant>0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Participantes internos o externos y su respuesta; un usuario puede tener muchos eventos';

CREATE TABLE IF NOT EXISTS crm_calendar_event_link (
  id_calendar_event_link BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna del vinculo del evento con un registro CRM',
  event_id_calendar_event_link BIGINT UNSIGNED NOT NULL COMMENT 'Evento relacionado sin copiar la transaccion comercial',
  entity_type_calendar_event_link VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Tipo canonico autorizado por el futuro registro API: lead, sales_order, estimate u otro',
  entity_public_id_calendar_event_link CHAR(26) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ULID publico nativo del registro; API valida existencia y permiso; no admite ID ERP',
  created_by_user_id_calendar_event_link BIGINT UNSIGNED NOT NULL COMMENT 'Usuario que vinculo el registro al evento',
  created_at_calendar_event_link DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Creacion del vinculo en UTC',
  updated_at_calendar_event_link DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima modificacion del vinculo en UTC',
  deleted_at_calendar_event_link DATETIME(3) NULL COMMENT 'Retiro logico del vinculo; los cambios deben quedar en auditoria central',
  PRIMARY KEY (id_calendar_event_link),
  UNIQUE KEY uq_calendar_link_target (event_id_calendar_event_link,entity_type_calendar_event_link,entity_public_id_calendar_event_link),
  KEY ix_calendar_link_entity (entity_type_calendar_event_link,entity_public_id_calendar_event_link,deleted_at_calendar_event_link,event_id_calendar_event_link),
  FOREIGN KEY (event_id_calendar_event_link) REFERENCES crm_calendar_event(id_calendar_event),
  FOREIGN KEY (created_by_user_id_calendar_event_link) REFERENCES sec_user(id_user),
  CONSTRAINT ck_calendar_link_identity CHECK (entity_type_calendar_event_link REGEXP '^[a-z][a-z0-9_]*$' AND entity_public_id_calendar_event_link REGEXP '^[0-9A-HJKMNP-TV-Z]{26}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Vinculos dinamicos por tipo y ULID; sin FK polimorfica ni dependencia de proveedores';

CREATE TABLE IF NOT EXISTS crm_calendar_appointment (
  event_id_calendar_appointment BIGINT UNSIGNED NOT NULL COMMENT 'Evento con detalle comercial de cita; como maximo un detalle por evento',
  lead_id_calendar_appointment BIGINT UNSIGNED NULL COMMENT 'Lead interno si la cita se asocia a un expediente existente',
  project_id_calendar_appointment BIGINT UNSIGNED NULL COMMENT 'Proyecto interno de la visita; su nombre se consulta en el catalogo',
  sequence_calendar_appointment INT UNSIGNED NULL COMMENT 'Numero de cita del seguimiento cuando negocio lo determine; no se infiere de flags antiguos',
  customer_confirmed_at_calendar_appointment DATETIME(3) NULL COMMENT 'Fecha UTC de confirmacion conocida del cliente',
  supervisor_verified_at_calendar_appointment DATETIME(3) NULL COMMENT 'Fecha UTC de verificacion por supervision',
  supervisor_user_id_calendar_appointment BIGINT UNSIGNED NULL COMMENT 'Usuario interno que verifico esta cita',
  progress_calendar_appointment VARCHAR(24) NULL COMMENT 'Progreso comercial planned, attended o missed cuando sea informado; null si se desconoce',
  created_at_calendar_appointment DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Creacion del detalle de cita en UTC',
  updated_at_calendar_appointment DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima modificacion del detalle en UTC',
  PRIMARY KEY (event_id_calendar_appointment),
  KEY ix_calendar_appointment_lead (lead_id_calendar_appointment,project_id_calendar_appointment,sequence_calendar_appointment),
  FOREIGN KEY (event_id_calendar_appointment) REFERENCES crm_calendar_event(id_calendar_event),
  FOREIGN KEY (lead_id_calendar_appointment) REFERENCES crm_lead(id_lead),
  FOREIGN KEY (project_id_calendar_appointment) REFERENCES crm_project(id_project),
  FOREIGN KEY (supervisor_user_id_calendar_appointment) REFERENCES sec_user(id_user),
  CONSTRAINT ck_calendar_appointment_sequence CHECK (sequence_calendar_appointment IS NULL OR sequence_calendar_appointment>0),
  CONSTRAINT ck_calendar_appointment_progress CHECK (progress_calendar_appointment IS NULL OR progress_calendar_appointment IN ('planned','attended','missed')),
  CONSTRAINT ck_calendar_appointment_verifier CHECK ((supervisor_verified_at_calendar_appointment IS NULL AND supervisor_user_id_calendar_appointment IS NULL) OR (supervisor_verified_at_calendar_appointment IS NOT NULL AND supervisor_user_id_calendar_appointment IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Datos opcionales de una cita comercial; no todos los eventos son citas de leads';

CREATE TABLE IF NOT EXISTS crm_calendar_notification (
  id_calendar_notification BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna de la notificacion individual de campana',
  public_id_calendar_notification CHAR(26) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ULID publico de la notificacion para marcar lectura propia',
  event_id_calendar_notification BIGINT UNSIGNED NOT NULL COMMENT 'Evento al que apunta; consultar el evento vuelve a verificar visibilidad',
  recipient_user_id_calendar_notification BIGINT UNSIGNED NOT NULL COMMENT 'Usuario interno destinatario; la lectura de otra persona no afecta esta fila',
  kind_calendar_notification VARCHAR(32) NOT NULL COMMENT 'Tipo invitation, event_updated, event_cancelled, event_today o reminder',
  dedupe_key_calendar_notification VARCHAR(120) NOT NULL COMMENT 'Clave idempotente: fecha local para event_today o version para otros avisos',
  visible_at_calendar_notification DATETIME(3) NOT NULL COMMENT 'Instante UTC desde el que aparece en la campana',
  expires_at_calendar_notification DATETIME(3) NULL COMMENT 'Fin UTC opcional de visibilidad; para hoy corresponde al siguiente dia local',
  read_at_calendar_notification DATETIME(3) NULL COMMENT 'Primera lectura o marca como leido por el destinatario; null significa pendiente',
  dismissed_at_calendar_notification DATETIME(3) NULL COMMENT 'Descarte individual UTC; no cancela el evento ni responde la invitacion',
  created_at_calendar_notification DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Creacion de la notificacion individual en UTC',
  updated_at_calendar_notification DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima modificacion UTC de la notificacion',
  PRIMARY KEY (id_calendar_notification),
  UNIQUE KEY uq_calendar_notification_public (public_id_calendar_notification),
  UNIQUE KEY uq_calendar_notification_dedupe (recipient_user_id_calendar_notification,event_id_calendar_notification,kind_calendar_notification,dedupe_key_calendar_notification),
  KEY ix_calendar_notification_unread (recipient_user_id_calendar_notification,read_at_calendar_notification,dismissed_at_calendar_notification,visible_at_calendar_notification,id_calendar_notification),
  FOREIGN KEY (event_id_calendar_notification) REFERENCES crm_calendar_event(id_calendar_event),
  FOREIGN KEY (recipient_user_id_calendar_notification) REFERENCES sec_user(id_user),
  CONSTRAINT ck_calendar_notification_kind CHECK (kind_calendar_notification IN ('invitation','event_updated','event_cancelled','event_today','reminder')),
  CONSTRAINT ck_calendar_notification_expiry CHECK (expires_at_calendar_notification IS NULL OR expires_at_calendar_notification>visible_at_calendar_notification),
  CONSTRAINT ck_calendar_notification_key CHECK (CHAR_LENGTH(TRIM(dedupe_key_calendar_notification))>0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Campana por usuario; lectura, descarte y respuesta al evento son acciones distintas';

CREATE TABLE IF NOT EXISTS int_calendar_connection (
  id_calendar_connection BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna de una cuenta y calendario externo configurados',
  public_id_calendar_connection CHAR(26) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ULID publico de la conexion de calendario',
  external_system_id_calendar_connection BIGINT UNSIGNED NOT NULL COMMENT 'Proveedor configurado en int_external_system; no activa ninguna integracion',
  owner_user_id_calendar_connection BIGINT UNSIGNED NOT NULL COMMENT 'Usuario interno responsable de esta conexion',
  external_tenant_id_calendar_connection VARCHAR(180) COLLATE utf8mb4_bin NOT NULL COMMENT 'Ambito de organizacion o tenant del proveedor',
  external_account_id_calendar_connection VARCHAR(180) COLLATE utf8mb4_bin NOT NULL COMMENT 'Identidad de buzon o cuenta; no es correo como clave de autenticacion',
  external_calendar_id_calendar_connection VARCHAR(1024) COLLATE utf8mb4_bin NOT NULL COMMENT 'Identidad del calendario dentro de la cuenta externa',
  calendar_key_calendar_connection BINARY(32) GENERATED ALWAYS AS (UNHEX(SHA2(external_calendar_id_calendar_connection,256))) STORED COMMENT 'Digest indexable de la identidad larga; no truncar ni ignorar colisiones',
  status_calendar_connection VARCHAR(16) NOT NULL DEFAULT 'inactive' COMMENT 'Estado active o inactive; por defecto no se sincroniza',
  created_at_calendar_connection DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Creacion de la configuracion en UTC',
  updated_at_calendar_connection DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima modificacion de configuracion UTC',
  PRIMARY KEY (id_calendar_connection),
  UNIQUE KEY uq_calendar_connection_public (public_id_calendar_connection),
  UNIQUE KEY uq_calendar_connection_scope (external_system_id_calendar_connection,external_tenant_id_calendar_connection,external_account_id_calendar_connection,calendar_key_calendar_connection),
  KEY ix_calendar_connection_owner (owner_user_id_calendar_connection,status_calendar_connection),
  FOREIGN KEY (external_system_id_calendar_connection) REFERENCES int_external_system(id_external_system),
  FOREIGN KEY (owner_user_id_calendar_connection) REFERENCES sec_user(id_user),
  CONSTRAINT ck_calendar_connection_status CHECK (status_calendar_connection IN ('active','inactive')),
  CONSTRAINT ck_calendar_connection_identity CHECK (CHAR_LENGTH(TRIM(external_tenant_id_calendar_connection))>0 AND CHAR_LENGTH(TRIM(external_account_id_calendar_connection))>0 AND CHAR_LENGTH(TRIM(external_calendar_id_calendar_connection))>0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Cuenta y calendario externos; sin contrasenas, tokens, secretos ni permisos Graph';

CREATE TABLE IF NOT EXISTS int_calendar_event_sync (
  id_calendar_event_sync BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Identidad interna de la sincronizacion del evento en un calendario externo',
  event_id_calendar_event_sync BIGINT UNSIGNED NOT NULL COMMENT 'Evento nativo que conserva autoridad de modulo aunque tenga copia externa',
  connection_id_calendar_event_sync BIGINT UNSIGNED NOT NULL COMMENT 'Cuenta y calendario externos destino; un evento puede usar varias conexiones',
  external_event_id_calendar_event_sync VARCHAR(1024) COLLATE utf8mb4_bin NULL COMMENT 'ID sensible a mayusculas del evento remoto; null antes de confirmarse',
  external_event_key_calendar_event_sync BINARY(32) GENERATED ALWAYS AS (UNHEX(SHA2(external_event_id_calendar_event_sync,256))) STORED COMMENT 'Digest para unicidad dentro de la conexion; adapter compara el valor completo',
  external_uid_calendar_event_sync VARCHAR(1024) COLLATE utf8mb4_bin NULL COMMENT 'UID del proveedor para conciliacion; no se considera unico globalmente',
  external_version_calendar_event_sync VARCHAR(1024) COLLATE utf8mb4_bin NULL COMMENT 'Version o ETag remoto para evitar sobrescrituras concurrentes',
  operation_id_calendar_event_sync VARCHAR(100) COLLATE utf8mb4_bin NOT NULL COMMENT 'Clave de idempotencia estable para crear el evento remoto sin duplicados',
  direction_calendar_event_sync VARCHAR(24) NOT NULL DEFAULT 'outbound' COMMENT 'Direccion outbound, inbound o bidirectional; no elude permisos de modulo',
  status_calendar_event_sync VARCHAR(24) NOT NULL DEFAULT 'pending' COMMENT 'Sincronizacion pending, synced, error o disabled; no demuestra envio de correo',
  desired_state_calendar_event_sync VARCHAR(16) NOT NULL DEFAULT 'present' COMMENT 'Estado remoto deseado present o absent; conserva ID al solicitar cancelacion',
  last_synced_version_calendar_event_sync INT UNSIGNED NULL COMMENT 'Version nativa confirmada por el proveedor',
  last_synced_at_calendar_event_sync DATETIME(3) NULL COMMENT 'Ultima sincronizacion confirmada UTC; null no significa enviada',
  attempt_count_calendar_event_sync INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Cantidad de intentos conocidos de sincronizacion',
  next_attempt_at_calendar_event_sync DATETIME(3) NULL COMMENT 'Proximo intento UTC definido por el futuro worker con control de reintentos',
  error_code_calendar_event_sync VARCHAR(100) NULL COMMENT 'Codigo sanitizado del fallo; nunca guardar tokens ni respuestas completas',
  created_at_calendar_event_sync DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Creacion del vinculo de sincronizacion en UTC',
  updated_at_calendar_event_sync DATETIME(3) NOT NULL DEFAULT (UTC_TIMESTAMP(3)) COMMENT 'Ultima modificacion de sincronizacion UTC',
  PRIMARY KEY (id_calendar_event_sync),
  UNIQUE KEY uq_calendar_sync_event_connection (event_id_calendar_event_sync,connection_id_calendar_event_sync),
  UNIQUE KEY uq_calendar_sync_remote (connection_id_calendar_event_sync,external_event_key_calendar_event_sync),
  UNIQUE KEY uq_calendar_sync_operation (connection_id_calendar_event_sync,operation_id_calendar_event_sync),
  KEY ix_calendar_sync_queue (status_calendar_event_sync,next_attempt_at_calendar_event_sync,id_calendar_event_sync),
  FOREIGN KEY (event_id_calendar_event_sync) REFERENCES crm_calendar_event(id_calendar_event),
  FOREIGN KEY (connection_id_calendar_event_sync) REFERENCES int_calendar_connection(id_calendar_connection),
  CONSTRAINT ck_calendar_sync_status CHECK (status_calendar_event_sync IN ('pending','synced','error','disabled')),
  CONSTRAINT ck_calendar_sync_direction CHECK (direction_calendar_event_sync IN ('outbound','inbound','bidirectional')),
  CONSTRAINT ck_calendar_sync_desired CHECK (desired_state_calendar_event_sync IN ('present','absent')),
  CONSTRAINT ck_calendar_sync_confirmed CHECK (status_calendar_event_sync<>'synced' OR (external_event_id_calendar_event_sync IS NOT NULL AND last_synced_at_calendar_event_sync IS NOT NULL AND last_synced_version_calendar_event_sync IS NOT NULL AND last_synced_version_calendar_event_sync>0)),
  CONSTRAINT ck_calendar_sync_identity CHECK (CHAR_LENGTH(TRIM(operation_id_calendar_event_sync))>0 AND (external_event_id_calendar_event_sync IS NULL OR CHAR_LENGTH(TRIM(external_event_id_calendar_event_sync))>0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Estado externo desacoplado; ausencia de fila significa evento solo CRM';
